package main
import("os";"fmt";"image/png";"image";"encoding/json";"github.com/ragassets/gateway/internal/render/roformat";"github.com/ragassets/gateway/internal/render/sprite";"github.com/ragassets/gateway/internal/render/raster";"github.com/ragassets/gateway/internal/render/geom")
func main(){ab,_:=os.ReadFile("/tmp/emotion.act");sb,_:=os.ReadFile("/tmp/emotion.spr");a,e:=roformat.ParseAct(ab);if e!=nil{panic(e)};s,e:=roformat.ParseSpr(sb);if e!=nil{panic(e)};sp:=sprite.New(a,s,sprite.TypeStandard);os.MkdirAll("/tmp/social-emotions",0755);meta:=map[string]interface{}{};for id:=0;id<12;id++{obj:=sp.DrawObjectsOfAction(id);delay:=a.Actions[id].Interval*25;meta[fmt.Sprint(id)]=map[string]interface{}{"delay":delay,"frames":len(obj.Children)};for frame,fo:=range obj.Children{im:=raster.NewRawImage(160,160);for li,so:=range fo.Children{as:=a.Sprites(id,frame)[li];raster.DrawSprite(&im,so,sp.Image(as.SprID,as.SprType),geom.Vec3{X:float32(so.BoundingBox.X1)+80,Y:float32(so.BoundingBox.Y1)+80})};f,_:=os.Create(fmt.Sprintf("/tmp/social-emotions/%d-%d.png",id,frame));png.Encode(f,im.ToNRGBARect(image.Rect(0,0,160,160)));f.Close()}};b,_:=json.Marshal(meta);os.WriteFile("/tmp/social-emotions/meta.json",b,0644)}
